select jsonb_build_object('users',(select count(*)from auth.users where id::text like'af310000-%'),'companies',(select count(*)from public.companies where id::text like'af310000-%'),'deals',(select count(*)from public.deals where company_id::text like'af310000-%'),'offers',(select count(*)from public.offers where company_id::text like'af310000-%'),'guestInvitations',(select count(*)from private.guest_document_invitations where company_id::text like'af310000-%'),'signings',(select count(*)from private.contract_signings where company_id::text like'af310000-%'),'guestSignatures',(select count(*)from private.guest_contract_signatures where invitation_id in(select id from private.guest_document_invitations where company_id::text like'af310000-%')),'payments',(select count(*)from private.deal_payment_entries where company_id::text like'af310000-%'),'deliveries',(select count(*)from private.deal_deliveries where company_id::text like'af310000-%'),'requests',(select count(*)from private.deal_fulfilment_requests where company_id::text like'af310000-%'),'outbox',(select count(*)from private.transactional_email_outbox where recipient in('guest-fulfilment-owner-af310000@example.invalid','guest-fulfilment-buyer-af310000@example.invalid')))result;
